// Deterministic progressive-stream tests against a local mock HTTP server.
//
// No live provider is contacted: a QTcpServer on loopback serves generated bytes
// with real HTTP semantics (Content-Length, Range/206, optional truncation and
// pacing), and the production RemoteStreamSource is driven exactly as the player
// drives it. The encrypted-import path uses the real core vault, so the "encrypt
// while downloading" claim is proven by readback rather than by inspection.

#include "videovault/app/remote_stream_source.hpp"
#include "videovault/app/plugin_host.hpp"
#include "videovault/app/media_decoder.hpp"
#include <QSettings>
#include "videovault/core/vault.hpp"

#include <QCoreApplication>
#include <QElapsedTimer>
#include <QHostAddress>
#include <QTcpServer>
#include <QTcpSocket>
#include <QTemporaryDir>
#include <QTimer>

#include <atomic>
#include <cstring>
#include <filesystem>
#include <iostream>
#include <memory>
#include <thread>
#include <vector>

namespace core = videovault::core;
using videovault::app::RemoteStreamSource;

namespace {

int fail(const char* message) {
    std::cerr << "FAIL: " << message << '\n';
    return 1;
}

#define CHECK(x)                                                                                      \
    do {                                                                                              \
        if (!(x)) {                                                                                   \
            std::cerr << "FAIL line " << __LINE__ << ": " #x << '\n';                                 \
            return 1;                                                                                 \
        }                                                                                             \
    } while (false)

// Serves one generated body per connection with real HTTP framing.
class MockStreamServer final : public QObject {
public:
    MockStreamServer(QByteArray body, bool honour_range, int chunk_bytes, int interval_ms,
        qint64 truncate_at)
        : body_(std::move(body)),
          honour_range_(honour_range),
          chunk_bytes_(chunk_bytes),
          interval_ms_(interval_ms),
          truncate_at_(truncate_at) {
        server_.listen(QHostAddress::LocalHost, 0);
        QObject::connect(&server_, &QTcpServer::newConnection, &server_, [this] {
            while (auto* socket = server_.nextPendingConnection()) {
                QObject::connect(socket, &QTcpSocket::readyRead, socket,
                    [this, socket] { serve(socket); });
                QObject::connect(socket, &QTcpSocket::disconnected, socket,
                    &QObject::deleteLater);
            }
        });
    }

    QUrl url() const {
        return QUrl(QStringLiteral("http://127.0.0.1:%1/track/1").arg(server_.serverPort()));
    }

    void redirectTo(QUrl target) { redirect_ = std::move(target); }
    void malformedRange() { malformed_ = true; }
    void unknownLength() { unknown_ = true; }
    void setTag(QByteArray value) { tag_ = std::move(value); }
    int requests() const { return requests_; }
    QString last_range() const { return last_range_; }
    QStringList all_ranges() const { return ranges_; }

private:
    void serve(QTcpSocket* socket) {
        const auto request = socket->readAll();
        if (request.isEmpty()) {
            return;
        }
        const auto text = QString::fromLatin1(request);
        std::int64_t start = 0;
        const auto range_line = text.indexOf(QStringLiteral("Range: bytes="));
        if (range_line >= 0) {
            const auto tail = text.mid(range_line + 13);
            const auto stop = tail.indexOf('-');
            if (stop > 0) {
                start = tail.left(stop).toLongLong();
                last_range_ = QStringLiteral("bytes=%1-").arg(start);
                ranges_.append(last_range_);
            }
        }
        ++requests_;
        if (!redirect_.isEmpty()) {
            socket->write("HTTP/1.1 302 Found\r\nLocation: " + redirect_.toEncoded() + "\r\nContent-Length: 0\r\n\r\n");
            socket->disconnectFromHost(); return;
        }
        const auto total = static_cast<std::int64_t>(body_.size());
        QByteArray payload;
        // A server that supports Range answers every ranged request with 206,
        // including "bytes=0-"; that is what makes the source report itself as
        // seekable.
        if (honour_range_ && start < total && !unknown_) {
            payload = body_.mid(static_cast<int>(start));
            socket->write("HTTP/1.1 206 Partial Content\r\n");
            if (!tag_.isEmpty()) socket->write("ETag: " + tag_ + "\r\n");
            socket->write(QByteArray("Content-Range: bytes ")
                + QByteArray::number(static_cast<qint64>(malformed_ ? start + 1 : start)) + "-"
                + QByteArray::number(static_cast<qint64>(total - 1)) + "/"
                + QByteArray::number(static_cast<qint64>(total)) + "\r\n");
            socket->write("Accept-Ranges: bytes\r\n");
            socket->write("Content-Type: audio/flac\r\n");
            socket->write(QByteArray("Content-Length: ")
                + QByteArray::number(static_cast<qint64>(payload.size())) + "\r\n\r\n");
        } else {
            payload = body_;
            socket->write("HTTP/1.1 200 OK\r\n");
            if (!tag_.isEmpty()) socket->write("ETag: " + tag_ + "\r\n");
            socket->write("Accept-Ranges: none\r\n");
            socket->write("Content-Type: audio/flac\r\n");
            if (!unknown_) socket->write(QByteArray("Content-Length: ")
                + QByteArray::number(static_cast<qint64>(payload.size())) + "\r\n");
            socket->write("Connection: close\r\n\r\n");
        }
        if (truncate_at_ > 0 && payload.size() > truncate_at_) {
            payload.truncate(static_cast<int>(truncate_at_));
        }
        if (chunk_bytes_ <= 0) {
            socket->write(payload);
            socket->flush();
            socket->disconnectFromHost();
            return;
        }
        // Paced delivery, so the reader really observes a partially arrived
        // track instead of a file that appeared in one piece.
        auto pending = std::make_shared<QByteArray>(payload);
        auto* timer = new QTimer(socket);
        timer->setInterval(interval_ms_);
        QObject::connect(timer, &QTimer::timeout, socket, [socket, pending, timer, this] {
            if (pending->isEmpty()) {
                timer->stop();
                timer->deleteLater();
                socket->disconnectFromHost();
                return;
            }
            const auto take = std::min<int>(chunk_bytes_, pending->size());
            socket->write(pending->left(take));
            socket->flush();
            *pending = pending->mid(take);
        });
        timer->start();
    }

    QTcpServer server_;
    QByteArray body_;
    bool honour_range_;
    int chunk_bytes_;
    int interval_ms_;
    qint64 truncate_at_;
    int requests_{0};
    QString last_range_;
    QStringList ranges_;
    QUrl redirect_;
    QByteArray tag_;
    bool malformed_ = false, unknown_ = false;
};

QByteArray deterministicBytes(const int size) {
    QByteArray bytes(size, Qt::Uninitialized);
    std::uint32_t state = 0x3919a7U;
    for (int i = 0; i < size; ++i) {
        state ^= state << 13; state ^= state >> 17; state ^= state << 5;
        bytes[i] = static_cast<char>(state & 0xff);
    }
    return bytes;
}

// Drains `want` bytes through the production read() path on a worker thread (the
// decode thread) while the main thread keeps the event loop alive.
struct ReaderResult {
    std::vector<char> bytes;
    int error{-999};
    qint64 first_chunk_ms{-1};
    qint64 received_at_first_chunk{0};
    qint64 total_at_first_chunk{-1};
};

ReaderResult readAll(RemoteStreamSource& source, const std::int64_t want, const std::int64_t offset = 0) {
    ReaderResult result;
    source.seek(offset, SEEK_SET);
    std::atomic_bool done{false};
    std::thread worker([&result, &source, want, &done] {
        std::vector<char> buffer;
        buffer.reserve(static_cast<std::size_t>(want));
        std::vector<unsigned char> window(64 * 1024);
        QElapsedTimer timer;
        timer.start();
        while (static_cast<std::int64_t>(buffer.size()) < want) {
            const auto remaining = static_cast<int>(
                std::min<std::int64_t>(static_cast<std::int64_t>(window.size()), want - static_cast<std::int64_t>(buffer.size())));
            const int got = source.read(window.data(), remaining);
            if (result.first_chunk_ms < 0 && got > 0) {
                result.first_chunk_ms = timer.elapsed();
                result.received_at_first_chunk = source.received_bytes();
                result.total_at_first_chunk = source.size();
            }
            if (got <= 0) {
                result.error = got;
                break;
            }
            buffer.insert(buffer.end(), reinterpret_cast<char*>(window.data()),
                reinterpret_cast<char*>(window.data()) + got);
        }
        result.error = result.error == -999 ? 0 : result.error;
        result.bytes = std::move(buffer);
        done.store(true);
    });
    QElapsedTimer guard;
    guard.start();
    while (guard.elapsed() < 60000) {
        QCoreApplication::processEvents();
        if (done.load()) {
            break;
        }
        std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
    if (!done.load()) source.cancel();
    worker.join();
    return result;
}

// Waits for a predicate while pumping the event loop.
template <typename Predicate>
bool waitFor(Predicate predicate, int timeout_ms = 20000) {
    QElapsedTimer timer;
    timer.start();
    while (!predicate() && timer.elapsed() < timeout_ms) {
        QCoreApplication::processEvents();
        std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
    return predicate();
}

} // namespace

int main(int argc, char** argv) {
    QCoreApplication app(argc, argv);
    // Explicit opt-in transport smoke, never part of deterministic CTest and
    // never a provider/key request. Exercises the real OS certificate store.
    if (qEnvironmentVariableIsSet("MVP_STREAM_TLS_SMOKE")) {
        RemoteStreamSource::Limits limits;
        limits.allowed_hosts = QStringList{"example.com"};
        limits.stall_timeout_ms = 15000;
        RemoteStreamSource source(QUrl("https://example.com/"), limits);
        source.start();
        const auto result = readAll(source, 128);
        if (result.bytes.empty()) std::cerr << source.errorString().toStdString() << '\n';
        CHECK(result.error == 0 && result.bytes.size() == 128);
        CHECK(source.finalUrl().scheme() == "https");
        source.cancel();
        std::cout << "Native HTTPS stream smoke passed (128 verified-TLS bytes).\n";
        return 0;
    }

    // --- 1. playback starts before the whole track arrives -------------------
    {
        const auto body = deterministicBytes(1024 * 1024);
        MockStreamServer server(body, true, 32 * 1024, 8, 0);
        RemoteStreamSource::Limits limits;
        limits.require_https = false; // loopback mock server, test fixture only
        limits.buffer_bytes = 1 << 20;
        limits.stall_timeout_ms = 15000;
        RemoteStreamSource source(server.url(), limits);
        source.start();
        auto reading = readAll(source, body.size());
        if (reading.error != 0) {
            std::cerr << "  read error=" << reading.error
                      << " source error='" << source.errorString().toStdString() << "'"
                      << " received=" << source.received_bytes()
                      << " size=" << source.size() << '\n';
        }
        CHECK(reading.error == 0);
        CHECK(static_cast<int>(reading.bytes.size()) == body.size());
        CHECK(std::memcmp(reading.bytes.data(), body.constData(), body.size()) == 0);
        // The first bytes were served while only a fraction of the track had
        // been received: this is the property "no full-file preload" means.
        CHECK(reading.received_at_first_chunk > 0);
        CHECK(reading.total_at_first_chunk == body.size());
        CHECK(reading.received_at_first_chunk < reading.total_at_first_chunk);
        CHECK(source.complete());
        CHECK(source.honours_ranges());
    }

    // --- 2. seeking: window hit costs nothing, a jump fetches a Range -------
    {
        const auto body = deterministicBytes(4 * 1024 * 1024);
        MockStreamServer server(body, true, 0, 0, 0);
        RemoteStreamSource::Limits limits;
        limits.require_https = false; // loopback mock server, test fixture only
        limits.buffer_bytes = 256 * 1024;
        RemoteStreamSource source(server.url(), limits);
        source.start();
        auto head = readAll(source, 32 * 1024);
        CHECK(head.error == 0);
        CHECK(std::memcmp(head.bytes.data(), body.constData(), 32 * 1024) == 0);

        // A jump beyond what has been prefetched opens exactly one Range request.
        const std::int64_t offset = 3 * 1024 * 1024;
        auto tail = readAll(source, 8 * 1024, offset);
        if (tail.error != 0) {
            std::cerr << "  seek read error=" << tail.error << " msg='"
                      << source.errorString().toStdString() << "' received="
                      << source.received_bytes() << '\n';
        }
        CHECK(tail.error == 0);
        CHECK(std::memcmp(tail.bytes.data(), body.constData() + offset, 8 * 1024) == 0);
        if (!server.all_ranges().contains(QStringLiteral("bytes=3145728-"))) {
            std::cerr << "  ranges seen:";
            for (const auto& r : server.all_ranges()) {
                std::cerr << ' ' << r.toStdString();
            }
            std::cerr << " requests=" << server.requests()
                      << " buffered=" << source.buffered_bytes()
                      << " received=" << source.received_bytes() << '\n';
        }
        CHECK(server.all_ranges().contains(QStringLiteral("bytes=3145728-")));

        // A seek inside what is already buffered is served from RAM: no request
        // is ever opened for that offset.
        auto near = readAll(source, 1024, offset + 1024);
        CHECK(near.error == 0);
        CHECK(std::memcmp(near.bytes.data(), body.constData() + offset + 1024, 1024) == 0);
        CHECK(!server.all_ranges().contains(QStringLiteral("bytes=3154944-")));
    }

    // --- 3. cancellation stops the fetch -----------------------------------
    {
        const auto body = deterministicBytes(512 * 1024);
        MockStreamServer server(body, true, 8 * 1024, 20, 0);
        RemoteStreamSource::Limits limits;
        limits.require_https = false; // loopback mock server, test fixture only
        limits.buffer_bytes = 1 << 20;
        RemoteStreamSource source(server.url(), limits);
        source.start();
        auto partial = readAll(source, 24 * 1024);
        CHECK(partial.error == 0);
        const auto received_before = source.received_bytes();
        source.cancel();
        auto after = readAll(source, 24 * 1024, 256 * 1024);
        // A cancelled source reads as end-of-stream and never opens a new
        // request, so nothing more arrives.
        CHECK(after.error == 0);
        CHECK(after.bytes.empty());
        QCoreApplication::processEvents();
        std::this_thread::sleep_for(std::chrono::milliseconds(120));
        QCoreApplication::processEvents();
        CHECK(source.received_bytes() == received_before);
    }

    // --- 4. a truncated body fails instead of looking finished --------------
    {
        const auto body = deterministicBytes(256 * 1024);
        MockStreamServer server(body, true, 16 * 1024, 2, 40 * 1024);
        RemoteStreamSource::Limits limits;
        limits.require_https = false; // loopback mock server, test fixture only
        limits.buffer_bytes = 1 << 20;
        limits.stall_timeout_ms = 1500;
        RemoteStreamSource source(server.url(), limits);
        source.start();
        auto reading = readAll(source, body.size());
        CHECK(reading.error == -1);
        CHECK(!source.complete());
        CHECK(!source.errorString().isEmpty());
    }

    // --- 5. a provider that ignores Range is reported as non-seekable ------
    {
        const auto body = deterministicBytes(128 * 1024);
        MockStreamServer server(body, false, 0, 0, 0);
        RemoteStreamSource::Limits limits;
        limits.require_https = false; // loopback mock server, test fixture only
        limits.buffer_bytes = 1 << 20;
        RemoteStreamSource source(server.url(), limits);
        source.start();
        auto reading = readAll(source, body.size());
        CHECK(reading.error == 0);
        CHECK(std::memcmp(reading.bytes.data(), body.constData(), body.size()) == 0);
        CHECK(!source.honours_ranges());
    }

    // --- 6. encrypt while downloading: one fetch feeds the vault ------------
    {
        QTemporaryDir directory;
        const auto root = std::filesystem::u8path(
            directory.path().toUtf8().constData()) / "vault";
        auto created = core::Vault::create(root, "progressive-stream-fixture", {8192, 1, 1});
        CHECK(created);
        auto vault = std::move(created.value());

        const auto body = deterministicBytes(700 * 1024);
        MockStreamServer server(body, true, 48 * 1024, 4, 0);
        RemoteStreamSource::Limits limits;
        limits.require_https = false; // loopback mock server, test fixture only
        limits.buffer_bytes = 256 * 1024;
        RemoteStreamSource source(server.url(), limits);

        core::TrackProvenance provenance;
        provenance.provider_id = "org.megavault.monochrome";
        provenance.provider_track_id = "stream-fixture-1";
        provenance.source_url = server.url().toString().toStdString();
        provenance.title = "Streamed";
        provenance.artist = "Fixture";
        provenance.codec = "flac";

        auto begun = vault.begin_stream_import(
            "Streamed.flac", static_cast<std::uint64_t>(body.size()), 0, &provenance);
        CHECK(begun);
        auto import = std::move(begun.value());

        // The tap encrypts on its own thread in production; here the sink pushes
        // straight into the core, which is the same code path minus the thread.
        std::atomic<bool> sink_failed{false};
        source.set_sink([&import, &sink_failed](std::int64_t offset, const char* data,
                            std::ptrdiff_t size) {
            if (import.written() != static_cast<std::uint64_t>(offset)) {
                sink_failed = true;
                return;
            }
            auto stored = import.append(std::span<const unsigned char>(
                reinterpret_cast<const unsigned char*>(data), static_cast<std::size_t>(size)));
            if (!stored) {
                sink_failed = true;
            }
        });
        source.start();

        auto playing = readAll(source, body.size());
        CHECK(playing.error == 0);
        CHECK(static_cast<int>(playing.bytes.size()) == body.size());
        CHECK(!sink_failed.load());
        CHECK(waitFor([&import] { return import.written() == import.expected_size(); }));

        auto committed = import.commit();
        CHECK(committed);
        const auto id = committed.value();
        auto stored = vault.read_video_bytes(id);
        CHECK(stored);
        CHECK(static_cast<int>(stored.value().size()) == body.size());
        CHECK(std::memcmp(stored.value().data(), body.constData(), body.size()) == 0);

        auto resolved = vault.find_video_by_provenance(provenance.provider_id,
            provenance.provider_track_id);
        CHECK(resolved && resolved.value() && resolved.value().value() == id);

        // No plaintext staging file anywhere in the vault tree.
        std::error_code error;
        for (const auto& entry : std::filesystem::recursive_directory_iterator(root, error)) {
            const auto name = entry.path().filename().string();
            const auto ext = entry.path().extension().string();
            if (ext == ".vvp" && entry.path().parent_path().filename() == ".tmp") {
                return fail("an uncommitted staging package was left behind");
            }
            if (ext == ".flac" || name.find("plain") != std::string::npos) {
                return fail("plaintext staging file found");
            }
        }
    }

    // --- 7. real asynchronous tap survives seek gaps and bounded RAM -------
    {
        QTemporaryDir directory;
        auto created = core::Vault::create(std::filesystem::path(directory.path().toStdWString()) / "vault",
            "tap-fixture", {8192, 1, 1});
        CHECK(created);
        auto vault = std::make_shared<core::Vault>(std::move(created.value()));
        const auto body = deterministicBytes(3 * 1024 * 1024);
        MockStreamServer server(body, true, 16 * 1024, 1, 0);
        RemoteStreamSource::Limits limits;
        limits.require_https = false; limits.buffer_bytes = 256 * 1024;
        limits.max_bytes = body.size(); // rereads must not count against object extent
        RemoteStreamSource source(server.url(), limits);
        core::TrackProvenance provenance;
        provenance.provider_id = "org.megavault.monochrome";
        provenance.provider_track_id = "seek-gap-fixture";
        videovault::app::RemoteStreamImport tap(source, vault, "Seek.flac", 0, provenance, false);
        source.start();
        const auto head = readAll(source, 32768);
        CHECK(head.bytes.size() == 32768);
        const auto tail = readAll(source, 8192, 2 * 1024 * 1024 + 123);
        CHECK(tail.bytes.size() == 8192);
        CHECK(std::memcmp(tail.bytes.data(), body.constData() + 2 * 1024 * 1024 + 123, 8192) == 0);
        const auto back = readAll(source, 8192, 12345);
        CHECK(back.bytes.size() == 8192);
        CHECK(std::memcmp(back.bytes.data(), body.constData() + 12345, 8192) == 0);
        CHECK(waitFor([&] { return tap.finished() || source.failed(); }));
        CHECK(!source.failed());
        CHECK(tap.committed());
        CHECK(source.buffered_bytes() <= limits.buffer_bytes);
        CHECK(tap.queuedBytes() <= 1024 * 1024);
        const auto stored = vault->read_video_bytes(tap.videoId());
        CHECK(stored && stored.value().size() == static_cast<std::size_t>(body.size()));
        CHECK(std::memcmp(stored.value().data(), body.constData(), body.size()) == 0);
        auto rows = vault->list_videos(); CHECK(rows && rows.value().size() == 1);
    }
    // --- 8. ignored Range across many windows (discard prefix, no deadlock) --
    {
        const auto body = deterministicBytes(900 * 1024);
        MockStreamServer server(body, false, 0, 0, 0);
        RemoteStreamSource::Limits limits;
        limits.require_https = false; limits.buffer_bytes = 256 * 1024;
        RemoteStreamSource source(server.url(), limits); source.start();
        const auto all = readAll(source, body.size());
        CHECK(all.bytes.size() == static_cast<std::size_t>(body.size()));
        CHECK(std::memcmp(all.bytes.data(), body.constData(), body.size()) == 0);
        const auto back = readAll(source, 8192, 12345);
        CHECK(back.bytes.size() == 8192);
        CHECK(std::memcmp(back.bytes.data(), body.constData() + 12345, 8192) == 0);
        CHECK(source.buffered_bytes() <= limits.buffer_bytes);
    }
    // --- 9. reject a redirect BEFORE contacting the destination ------------
    {
        MockStreamServer target(deterministicBytes(64), false, 0, 0, 0);
        auto forbidden = target.url(); forbidden.setHost("localhost");
        MockStreamServer server({}, false, 0, 0, 0); server.redirectTo(forbidden);
        RemoteStreamSource::Limits limits;
        limits.require_https = false; limits.allowed_hosts = QStringList{"127.0.0.1"};
        RemoteStreamSource source(server.url(), limits); source.start();
        CHECK(waitFor([&] { return source.failed(); }));
        CHECK(target.requests() == 0);
    }
    // --- 10. malformed/mismatched range is rejected before bytes -----------
    {
        MockStreamServer server(deterministicBytes(65536), true, 0, 0, 0); server.malformedRange();
        RemoteStreamSource::Limits limits; limits.require_https = false;
        RemoteStreamSource source(server.url(), limits); source.start();
        CHECK(waitFor([&] { return source.failed(); }));
        CHECK(source.received_bytes() == 0);
    }
    // --- 11. unknown length plays to EOF, refuses offline publication -------
    {
        QTemporaryDir directory;
        auto created = core::Vault::create(std::filesystem::path(directory.path().toStdWString()) / "vault",
            "unknown-fixture", {8192, 1, 1}); CHECK(created);
        auto vault = std::make_shared<core::Vault>(std::move(created.value()));
        const auto body = deterministicBytes(400 * 1024);
        MockStreamServer server(body, false, 8192, 1, 0); server.unknownLength();
        RemoteStreamSource::Limits limits; limits.require_https = false; limits.buffer_bytes = 256 * 1024;
        RemoteStreamSource source(server.url(), limits);
        videovault::app::RemoteStreamImport tap(source, vault, "Unknown.flac", 0, {}, false);
        source.start();
        const auto played = readAll(source, body.size() + 1);
        CHECK(played.bytes.size() == static_cast<std::size_t>(body.size()));
        CHECK(source.size() == -1);
        CHECK(waitFor([&] { return tap.finished(); })); CHECK(!tap.committed());
        CHECK(!tap.errorString().isEmpty());
        auto rows = vault->list_videos(); CHECK(rows && rows.value().empty());
    }
    // --- 12. lock/cancellation clean up an active worker import ------------
    {
        QTemporaryDir directory;
        const auto root = std::filesystem::path(directory.path().toStdWString()) / "vault";
        auto created = core::Vault::create(root, "lock-fixture", {8192, 1, 1}); CHECK(created);
        auto vault = std::make_shared<core::Vault>(std::move(created.value()));
        MockStreamServer server(deterministicBytes(2 * 1024 * 1024), true, 8192, 2, 0);
        RemoteStreamSource::Limits limits; limits.require_https = false;
        RemoteStreamSource source(server.url(), limits);
        videovault::app::RemoteStreamImport tap(source, vault, "Locked.flac", 0, {}, false);
        source.start(); CHECK(waitFor([&] { return source.received_bytes() >= 32768; }));
        vault->lock(); source.cancel(); tap.cancel();
        CHECK(waitFor([&] { return tap.finished(); })); CHECK(!tap.committed());
        std::error_code error;
        for (const auto& entry : std::filesystem::recursive_directory_iterator(root, error))
            CHECK(!(entry.path().extension() == ".vvp" && entry.path().parent_path().filename() == ".tmp"));
    }
    // --- 13. persisted local identity bypasses the downloader fetch seam ----
    {
        QTemporaryDir directory;
        QCoreApplication::setOrganizationName("MegaVaultProgressiveFixture");
        QCoreApplication::setApplicationName("LocalFirst");
        QSettings::setDefaultFormat(QSettings::IniFormat);
        QSettings::setPath(QSettings::IniFormat, QSettings::UserScope, directory.path());
        videovault::app::PluginHost host(directory.path() + "/plugins");
        CHECK(host.setEnabled("org.megavault.monochrome", true));
        auto created = core::Vault::create(std::filesystem::path(directory.path().toStdWString()) / "vault",
            "local-first-fixture", {8192, 1, 1}); CHECK(created);
        auto vault = std::make_shared<core::Vault>(std::move(created.value()));
        videovault::app::PluginTrackDownloader downloader(&host);
        downloader.setVault(vault);
        int fetches = 0;
        auto body = deterministicBytes(130 * 1024);
        body.replace(0, 8, QByteArray("fLaC\0\0\0\x22", 8));
        downloader.setFetcher([&](const QString&, auto progress, auto done) {
            ++fetches; progress(body.size(), body.size()); done(body, {});
        });
        const QString id = "12345678901234567";
        const QJsonObject track{{"_id", id}, {"title", "Persisted"}};
        downloader.enqueue(track);
        CHECK(waitFor([&] { return downloader.state(id) == videovault::app::PluginTrackDownloader::Saved
            || downloader.state(id) == videovault::app::PluginTrackDownloader::Failed; }));
        CHECK(downloader.state(id) == videovault::app::PluginTrackDownloader::Saved);
        CHECK(fetches == 1);
        const auto local = vault->find_video_by_provenance("org.megavault.monochrome", id.toStdString());
        CHECK(local && local.value());
        downloader.setVault(nullptr); // discard the in-memory row state
        vault->lock();
        auto reopened = core::Vault::open(std::filesystem::path(directory.path().toStdWString()) / "vault", "local-first-fixture");
        CHECK(reopened);
        vault = std::make_shared<core::Vault>(std::move(reopened.value()));
        downloader.setVault(vault);
        downloader.enqueue(track);
        CHECK(downloader.state(id) == videovault::app::PluginTrackDownloader::Saved);
        CHECK(fetches == 1); // neither network nor injected fetch was invoked
        auto rows = vault->list_videos(); CHECK(rows && rows.value().size() == 1);
    }
    // --- 14. deterministic slow sink: backpressure never blocks event loop --
    {
        MockStreamServer server(deterministicBytes(1024 * 1024), true, 0, 0, 0);
        RemoteStreamSource::Limits limits; limits.require_https = false; limits.buffer_bytes = 256 * 1024;
        RemoteStreamSource source(server.url(), limits);
        bool ready = false; qint64 written = 0; int heartbeats = 0;
        source.set_sink_ready([&] { return ready; });
        bool outOfOrder = false;
        source.set_sink([&](std::int64_t offset, const char*, std::ptrdiff_t count) {
            if (offset != written) outOfOrder = true;
            written += count;
        });
        QTimer heartbeat; heartbeat.setInterval(1);
        QObject::connect(&heartbeat, &QTimer::timeout, [&] { ++heartbeats; }); heartbeat.start();
        source.start();
        CHECK(waitFor([&] { return heartbeats >= 20; }, 3000));
        CHECK(source.received_bytes() == 0);
        ready = true;
        CHECK(waitFor([&] { return written == 1024 * 1024 || source.failed(); }));
        CHECK(!source.failed() && !outOfOrder && written == 1024 * 1024);
        CHECK(source.buffered_bytes() <= limits.buffer_bytes);
    }
    // --- 15. FLAC validation spans partial reads, invalid headers fail ------
    {
        QByteArray body(128, '\0'); body.replace(0, 8, QByteArray("fLaC\0\0\0\x22", 8));
        MockStreamServer server(body, true, 1, 1, 0);
        RemoteStreamSource::Limits limits; limits.require_https = false; limits.require_flac = true;
        RemoteStreamSource source(server.url(), limits); source.start();
        const auto played = readAll(source, body.size());
        CHECK(played.bytes.size() == static_cast<std::size_t>(body.size()));
        CHECK(std::memcmp(played.bytes.data(), body.constData(), body.size()) == 0);
        MockStreamServer invalid(deterministicBytes(128), true, 0, 0, 0);
        RemoteStreamSource rejected(invalid.url(), limits); rejected.start();
        CHECK(waitFor([&] { return rejected.failed(); }));
        CHECK(rejected.bytes_served() == 0 && !rejected.complete());
    }
    // --- 16. real FFmpeg audio decode starts before the body arrives -------
    {
        const int pcmSize = 44100 * 2 * 60;
        QByteArray wav(44 + pcmSize, '\0');
        auto put32 = [&](int at, std::uint32_t value) {
            for (int i = 0; i < 4; ++i) wav[at + i] = static_cast<char>((value >> (i * 8)) & 255);
        };
        auto put16 = [&](int at, std::uint16_t value) {
            wav[at] = static_cast<char>(value & 255); wav[at + 1] = static_cast<char>(value >> 8);
        };
        wav.replace(0, 4, "RIFF"); put32(4, 36 + pcmSize); wav.replace(8, 8, "WAVEfmt ");
        put32(16, 16); put16(20, 1); put16(22, 1); put32(24, 44100);
        put32(28, 88200); put16(32, 2); put16(34, 16); wav.replace(36, 4, "data"); put32(40, pcmSize);
        MockStreamServer server(wav, true, 8192, 1, 0);
        RemoteStreamSource::Limits limits; limits.require_https = false; limits.buffer_bytes = 256 * 1024;
        RemoteStreamSource source(server.url(), limits); source.start();
        std::atomic_bool done{false}; bool decoded = false; qint64 atFirstPcm = 0; QString error;
        std::thread worker([&] {
            videovault::app::MediaDecoder decoder; decoder.prepare_for_audio();
            if (decoder.open_source(&source, &error, "fixture.wav") && decoder.has_audio()) {
                std::int64_t pts = 0;
                decoded = decoder.pump_audio(8192, &pts) && !decoder.take_audio_samples().empty();
                atFirstPcm = source.received_bytes();
            }
            done = true;
        });
        const bool completed = waitFor([&] { return done.load(); });
        if (!completed) source.cancel();
        worker.join();
        if (!decoded) std::cerr << "Decoder: " << error.toStdString() << '\n';
        CHECK(completed && decoded);
        CHECK(atFirstPcm > 0 && atFirstPcm < wav.size());
        CHECK(source.buffered_bytes() <= limits.buffer_bytes);
        source.cancel();
    }
    // --- 17. resumed ranges cannot silently splice a changed representation -
    {
        MockStreamServer server(deterministicBytes(1024 * 1024), true, 8192, 1, 0);
        server.setTag("\"v1\"");
        RemoteStreamSource::Limits limits; limits.require_https = false; limits.buffer_bytes = 256 * 1024;
        RemoteStreamSource source(server.url(), limits); source.start();
        const auto head = readAll(source, 8192); CHECK(head.bytes.size() == 8192);
        server.setTag("\"v2\"");
        const auto tail = readAll(source, 8192, 800 * 1024);
        CHECK(tail.error == -1 && tail.bytes.empty());
        CHECK(source.failed());
    }
    std::cout << "Progressive stream tests passed.\n";
    return 0;
}
